import{_ as t,o as e,c as s,ao as l}from"./chunks/framework.AQkxRU0n.js";const u=JSON.parse('{"title":"バックエンドとフォールバック","description":"","frontmatter":{},"headers":[],"relativePath":"manual/backend.md","filePath":"manual/backend.md","lastUpdated":null}'),n={name:"manual/backend.md"};function i(d,a,p,o,r,c){return e(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="バックエンドとフォールバック" tabindex="-1">バックエンドとフォールバック <a class="header-anchor" href="#バックエンドとフォールバック" aria-label="Permalink to &quot;バックエンドとフォールバック {#バックエンドとフォールバック}&quot;">​</a></h1><h2 id="呼び出しの流れ" tabindex="-1">呼び出しの流れ <a class="header-anchor" href="#呼び出しの流れ" aria-label="Permalink to &quot;呼び出しの流れ {#呼び出しの流れ}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Julia Matrix / Vector と LinearAlgebra</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>           libblastrampoline</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>        libcolmat_blas の BLAS ABI</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>       Rust colmat / Rust 互換層</span></span></code></pre></div><p><code>Colmat.__init__()</code> は <code>Colmat.load_backend()</code> を実行します。 ライブラリの存在と互換層の ABI バージョンを確認し、ILP64、LP64 の順に <code>BLAS.lbt_forward</code> で登録します。</p><p>Julia の配列は呼び出し中だけ Rust が借用します。Julia 側に Rust の行列所有権や 寿命管理用ハンドルを公開しません。<code>mul!</code> などの変更規則は Julia の API に従います。</p><h2 id="未提供ルーチンの扱い" tabindex="-1">未提供ルーチンの扱い <a class="header-anchor" href="#未提供ルーチンの扱い" aria-label="Permalink to &quot;未提供ルーチンの扱い {#未提供ルーチンの扱い}&quot;">​</a></h2><p>登録には <code>clear=false</code> を指定します。Colmat が提供するシンボルを置き換え、 未提供の BLAS と LAPACK の転送先は保持します。</p><table tabindex="0"><thead><tr><th style="text-align:right;">呼び出し</th><th style="text-align:right;">実行先</th></tr></thead><tbody><tr><td style="text-align:right;">対応する型の GEMM / GEMV など</td><td style="text-align:right;">Colmat</td></tr><tr><td style="text-align:right;">帯・packed 格納や未提供 BLAS</td><td style="text-align:right;">既存の転送先</td></tr><tr><td style="text-align:right;">LAPACK の LU / SVD / 固有値分解など</td><td style="text-align:right;">既存の転送先</td></tr><tr><td style="text-align:right;">整数や BigFloat など、この BLAS の対象外の型</td><td style="text-align:right;">Julia の型ごとの既存実装</td></tr></tbody></table><p>フォールバック側の共有ライブラリ内部から呼ぶ BLAS が LBT を経由するかは、 そのライブラリのリンク構成に依存します。LAPACK をロードしたままにすることと、 その分解がすべて Colmat で計算されることは同じではありません。 疎行列ソルバーの選択も、このパッケージのロードだけでは置き換えません。</p><h2 id="切り替えの範囲と順序" tabindex="-1">切り替えの範囲と順序 <a class="header-anchor" href="#切り替えの範囲と順序" aria-label="Permalink to &quot;切り替えの範囲と順序 {#切り替えの範囲と順序}&quot;">​</a></h2><p>変更は Julia プロセス全体に適用され、LBT を経由する他パッケージにも影響します。 計算ごと、配列ごと、Julia Task ごとの設定ではありません。</p><p>別の BLAS プロバイダーを後からロードすると、そのプロバイダーが転送先を変更する 場合があります。Colmat を再選択するときは次を実行します。</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Colmat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">load_backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>この呼び出しも未提供ルーチンの現在の転送先を保持します。最初の OpenBLAS 構成へ 戻す操作や、フォールバックを特定ライブラリに固定する操作ではありません。</p><p>バックエンドの切り替えは並列 BLAS 計算を開始する前に済ませてください。 Colmat 内部の設定ロックは、他パッケージや直接の LBT 操作を同期しません。</p>`,15)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
